messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Racing Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 5, 10);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(10, 20, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    scene.add(dirLight);

    // --- Track & Environment ---
    // Ground
    const groundGeo = new THREE.PlaneGeometry(20, 1000);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(10, 2);
    const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff }); // Checkerboard style (simplification)
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.05, -40); // Fixed position in world
    scene.add(finishLine);

    // Finish Pole
    const poleGeo = new THREE.BoxGeometry(0.2, 4, 0.2);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0xdddddd });
    const pole = new THREE.Mesh(poleGeo, poleMat);
    pole.position.set(0, 2, -40.1);
    scene.add(pole);

    // --- Car Factory ---
    function createCar(color) {
        const carGroup = new THREE.Group();

        // Chassis
        const chassisGeo = new THREE.BoxGeometry(2, 0.8, 4);
        const chassisMat = new THREE.MeshStandardMaterial({ color: color });
        const chassis = new THREE.Mesh(chassisGeo, chassisMat);
        chassis.position.y = 0.8;
        chassis.castShadow = true;
        carGroup.add(chassis);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.5;
        cabin.position.z = -0.2;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.5, 0.5, 0.4, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

        const positions = [
            { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 },
            { x: -1.1, z: -1.2 }, { x: 1.1, z: -1.2 }
        ];

        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(pos.x, 0.5, pos.z);
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        return carGroup;
    }

    // --- Race Logic ---
    const redCar = createCar(0xff0000);
    const blueCar = createCar(0x0000ff);
    scene.add(redCar);
    scene.add(blueCar);

    const finishZ = -40;
    const trackLength = 200; // Virtual length
    let raceState = 'start'; // start, racing, finished

    // Animation variables
    let time = 0;

    // Helper to get distance from start (z is negative, so we invert)
    function getDistance(car) {
        return Math.abs(car.position.z);
    }

    // --- Animation Loop ---
    function animate() {
        requestAnimationFrame(animate);

        // Reset if finished
        if (raceState === 'finished') {
            raceState = 'start';
            redCar.position.z = 0;
            blueCar.position.z = 0;
            redCar.position.y = 0;
            blueCar.position.y = 0;
            redCar.rotation.x = 0;
            blueCar.rotation.x = 0;
            redCar.rotation.z = 0;
            blueCar.rotation.z = 0;
            return;
        }

        // Logic based on raceState
        if (raceState === 'start') {
            // 1. Blue accelerates to lead
            if (blueCar.position.z < -5) {
                blueCar.position.z -= 0.2;
                blueCar.rotation.x = -0.1; // Tilt forward
                blueCar.rotation.z = 0.1; // Slight turn
            } else {
                // Start Red
                redCar.position.z -= 0.1;
                redCar.rotation.x = -0.1;
                redCar.rotation.z = 0.1;
            }
        } 
        else if (raceState === 'racing') {
            // 2. Blue maintains steady speed
            blueCar.position.z -= 0.2;

            // 3. Red accelerates heavily
            redCar.position.z -= 0.4; // Faster than blue

            // Add visual vibration/speed lines effect (simple wobble)
            redCar.rotation.z = (Math.random() - 0.5) * 0.05;
            blueCar.rotation.z = (Math.random() - 0.5) * 0.02;

            // Check for Overtake
            if (redCar.position.z < blueCar.position.z && redCar.position.z > -45) {
                raceState = 'finished'; // Red is ahead (more negative Z)
            }
        }

        // --- Camera Follow ---
        // Calculate average position of both cars for camera tracking
        const avgZ = (redCar.position.z + blueCar.position.z) / 2;

        // Smoothly interpolate camera Z position
        const targetCamZ = avgZ + 15; // Keep camera 15 units behind the pack
        camera.position.z += (targetCamZ - camera.position.z) * 0.1;

        // Keep camera centered on X (0)
        camera.position.x = 0;
        camera.position.y = 5;
        camera.lookAt(0, 0, avgZ - 5);

        // --- Render ---
        renderer.render(scene, camera);
    }

    // Handle resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>
</body>
</html>
```
